{"total_lines": 144, "text": "1: // WebAssembly platform layer for doomgeneric (Emscripten, Asyncify).
2: //
3: // - Rendering: DG_DrawFrame converts the engine's B,G,R,0 pixels to opaque
4: //   RGBA and blits to <canvas id="canvas"> via putImageData.
5: // - Timing: DG_GetTicksMs uses emscripten_get_now(); DG_SleepMs yields to the
6: //   browser with emscripten_sleep (Asyncify) so wipe/tic waits don't freeze it.
7: // - Input: JS calls dg_key(pressed, doomKey); DG_GetKey drains a ring buffer.
8: // - Entry: main() creates the game then ticks forever, yielding every frame.
9: 
10: #include <stdint.h>
11: #include <stdlib.h>
12: #include <stdio.h>
13: #include <string.h>
14: #include <emscripten.h>
15: 
16: #include "doomgeneric.h"
17: #include "doomstat.h"
18: 
19: #define KEYQ_SIZE 256
20: static struct { unsigned char pressed, key; } keyq[KEYQ_SIZE];
21: static unsigned keyq_r, keyq_w;
22: 
23: static uint32_t rgba[DOOMGENERIC_RESX * DOOMGENERIC_RESY];
24: static uint32_t frame_count, tick_count;
25: 
26: EM_JS(void, js_present, (const uint32_t *px, int w, int h), {
27:     var c = Module.canvas || document.getElementById('canvas');
28:     if (!c) return;
29:     if (!Module.__ctx) {
30:         Module.__ctx = c.getContext('2d');
31:         Module.__img = null;
32:     }
33:     if (!Module.__img || Module.__img.width != w || Module.__img.height != h)
34:         Module.__img = Module.__ctx.createImageData(w, h);
35:     Module.__img.data.set(HEAPU8.subarray(px, px + w * h * 4));
36:     Module.__ctx.putImageData(Module.__img, 0, 0);
37: });
38: 
39: EM_JS(void, js_title, (const char *t), {
40:     document.title = UTF8ToString(t);
41: });
42: 
43: void DG_Init() {}
44: 
45: void DG_DrawFrame()
46: {
47:     const uint32_t *src = (const uint32_t *)DG_ScreenBuffer;
48:     for (int i = 0; i < DOOMGENERIC_RESX * DOOMGENERIC_RESY; i++) {
49:         uint32_t p = src[i];                       // 0x00RRGGBB
50:         rgba[i] = 0xFF000000u | ((p & 0xFF) << 16) | (p & 0xFF00) |
51:                   ((p >> 16) & 0xFF);              // bytes R,G,B,255
52:     }
53:     js_present(rgba, DOOMGENERIC_RESX, DOOMGENERIC_RESY);
54:     frame_count++;
55: }
56: 
57: void DG_SleepMs(uint32_t ms)
58: {
59:     emscripten_sleep(ms);
60: }
61: 
62: uint32_t DG_GetTicksMs()
63: {
64:     return (uint32_t)emscripten_get_now();
65: }
66: 
67: int DG_GetKey(int *pressed, unsigned char *key)
68: {
69:     if (keyq_r == keyq_w) return 0;
70:     *pressed = keyq[keyq_r % KEYQ_SIZE].pressed;
71:     *key = keyq[keyq_r % KEYQ_SIZE].key;
72:     keyq_r++;
73:     return 1;
74: }
75: 
76: void DG_SetWindowTitle(const char *title)
77: {
78:     js_title(title);
79: }
80: 
81: EMSCRIPTEN_KEEPALIVE void dg_key(int pressed, int key)
82: {
83:     if (keyq_w - keyq_r >= KEYQ_SIZE || key <= 0 || key > 255) return;
84:     keyq[keyq_w % KEYQ_SIZE].pressed = pressed ? 1 : 0;
85:     keyq[keyq_w % KEYQ_SIZE].key = (unsigned char)key;
86:     keyq_w++;
87: }
88: 
89: EMSCRIPTEN_KEEPALIVE uint32_t dg_frame_count(void) { return frame_count; }
90: EMSCRIPTEN_KEEPALIVE uint32_t dg_tick_count(void) { return tick_count; }
91: 
92: // Read-only observations for browser verification. gametic counts simulation
93: // tics; tick_count above counts outer loop calls and is not a timing metric.
94: EMSCRIPTEN_KEEPALIVE int dg_game_tics(void) { return gametic; }
95: EMSCRIPTEN_KEEPALIVE int dg_menu_active(void) { return menuactive; }
96: EMSCRIPTEN_KEEPALIVE int dg_in_level(void) {
97:     return gamestate == GS_LEVEL && !demoplayback && players[consoleplayer].mo != NULL;
98: }
99: EMSCRIPTEN_KEEPALIVE int dg_player_x(void) {
100:     return players[consoleplayer].mo ? players[consoleplayer].mo->x : 0;
101: }
102: EMSCRIPTEN_KEEPALIVE int dg_player_y(void) {
103:     return players[consoleplayer].mo ? players[consoleplayer].mo->y : 0;
104: }
105: EMSCRIPTEN_KEEPALIVE uint32_t dg_player_angle(void) {
106:     return players[consoleplayer].mo ? players[consoleplayer].mo->angle : 0;
107: }
108: EMSCRIPTEN_KEEPALIVE int dg_bullets(void) { return players[consoleplayer].ammo[am_clip]; }
109: EMSCRIPTEN_KEEPALIVE int dg_use_down(void) { return players[consoleplayer].usedown; }
110: EMSCRIPTEN_KEEPALIVE int dg_paused(void) { return paused; }
111: EMSCRIPTEN_KEEPALIVE int dg_automap(void) { return automapactive; }
112: EMSCRIPTEN_KEEPALIVE int dg_weapon(void) { return players[consoleplayer].readyweapon; }
113: EMSCRIPTEN_KEEPALIVE int dg_forward(void) { return players[consoleplayer].cmd.forwardmove; }
114: EMSCRIPTEN_KEEPALIVE int dg_side(void) { return players[consoleplayer].cmd.sidemove; }
115: 
116: EM_JS(void, js_fatal, (const char *t), {
117:     var m = UTF8ToString(t);
118:     var s = document.getElementById('status');
119:     if (s) s.textContent = m;
120:     console.error(m);
121:     Module.__fatal = m;
122: });
123: 
124: int main(int argc, char **argv)
125: {
126:     (void)argc; (void)argv;
127:     // Fail visibly if the preloaded WAD is missing or not an IWAD.
128:     FILE *wf = fopen("/doom1.wad", "rb");
129:     char magic[4] = {0};
130:     if (!wf || fread(magic, 1, 4, wf) != 4 || memcmp(magic, "IWAD", 4) != 0) {
131:         js_fatal("Cannot start: /doom1.wad is missing or not a valid IWAD. Serve doom.data next to doom.js.");
132:         if (wf) fclose(wf);
133:         return 1;
134:     }
135:     fclose(wf);
136:     char *args[] = { "doom", "-iwad", "/doom1.wad", "-nogui", NULL };
137:     doomgeneric_Create(4, args);
138:     for (;;) {
139:         doomgeneric_Tick();
140:         tick_count++;
141:         emscripten_sleep(0);   // let the browser handle events/paint
142:     }
143:     return 0;
144: }"}

{"total_lines": 121, "text": "1: <!doctype html>
2: <html lang="en">
3: <head>
4:   <meta charset="utf-8">
5:   <title>Doom (WASM)</title>
6:   <meta name="viewport" content="width=device-width, initial-scale=1">
7:   <style>
8:     html, body { margin: 0; height: 100%; background: #000; }
9:     body { display: flex; align-items: center; justify-content: center; flex-direction: column; color: #ccc; font: 14px monospace; }
10:     canvas { background: #111; max-width: 100vw; max-height: 75vh; image-rendering: pixelated; outline: none; }
11:     .toolbar { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; justify-content: center; margin: 10px; }
12:     button { padding: 8px 14px; background: #292929; color: white; border: 1px solid #777; border-radius: 4px; cursor: pointer; }
13:     button:focus-visible, input:focus-visible { outline: 2px solid #f6c44c; }
14:     #controls { text-align: center; padding: 8px; max-width: 640px; line-height: 1.6; }
15:   </style>
16: </head>
17: <body>
18:   <canvas id="canvas" width="640" height="400" tabindex="0"></canvas>
19:   <div id="status">Loading…</div>
20:   <div class="toolbar" aria-label="Game controls">
21:     <button id="menu" disabled>Menu</button>
22:     <button id="pause" disabled aria-pressed="false">Pause</button>
23:     <button id="sound" aria-pressed="false">Enable sound</button>
24:     <label>Volume <input id="volume" type="range" min="0" max="100" value="70"></label>
25:   </div>
26:   <div id="controls">Arrows: move/turn · W/S: forward/back · A/D: strafe · Ctrl: fire · Space: use<br>Shift: run · 1–7: weapon · Tab: map · Enter/Esc: menus · P: pause</div>
27:   <script src="audio.js"></script>
28:   <script>
29:     // Browser KeyboardEvent.code -> Doom key code (doomkeys.h)
30:     const MAP = {
31:       ArrowLeft: 0xac, ArrowRight: 0xae, ArrowUp: 0xad, ArrowDown: 0xaf,
32:       ControlLeft: 0xa3, ControlRight: 0xa3, Space: 0xa2,
33:       Comma: 0xa0, Period: 0xa1,
34:       KeyW: 0xad, KeyS: 0xaf, KeyA: 0xa0, KeyD: 0xa1, KeyP: 0xff,
35:       Enter: 13, NumpadEnter: 13, Escape: 27, Tab: 9, Backspace: 0x7f,
36:       ShiftLeft: 0x80 + 0x36, ShiftRight: 0x80 + 0x36,
37:       AltLeft: 0x80 + 0x38, AltRight: 0x80 + 0x38,
38:       Minus: 0x2d, Equal: 0x3d, Pause: 0xff,
39:       F1: 0xbb, F2: 0xbc, F3: 0xbd, F4: 0xbe, F5: 0xbf, F6: 0xc0,
40:       F7: 0xc1, F8: 0xc2, F9: 0xc3, F10: 0xc4, F11: 0xd7, F12: 0xd8,
41:     };
42:     function doomKey(e) {
43:       if (MAP[e.code] !== undefined) return MAP[e.code];
44:       if (/^Key[A-Z]$/.test(e.code)) return e.code.charCodeAt(3) + 32; // lowercase
45:       if (/^Digit[0-9]$/.test(e.code)) return e.code.charCodeAt(5);
46:       return 0;
47:     }
48:     const down = new Map(); // physical key -> Doom key; aliases may overlap
49:     function unlockAudio() {
50:       DoomAudio.unlock().catch(error => { document.getElementById('status').textContent = `Sound unavailable: ${error.message}`; });
51:     }
52:     function release(code) {
53:       const k = down.get(code);
54:       if (k === undefined) return;
55:       down.delete(code);
56:       if (![...down.values()].includes(k)) Module._dg_key(0, k);
57:     }
58:     function send(pressed, e) {
59:       if (!pressed) { release(e.code); return; }
60:       if (e.target.closest?.('button, input, select, textarea')) return;
61:       const k = doomKey(e);
62:       if (!k || !Module._dg_key || e.metaKey) return;
63:       if (['F5','F11','F12'].includes(e.code)) return;
64:       e.preventDefault(); unlockAudio();
65:       if (down.has(e.code)) return;
66:       const held = [...down.values()].includes(k);
67:       down.set(e.code, k);
68:       if (!held) Module._dg_key(1, k);
69:     }
70:     window.addEventListener('keydown', e => send(true, e));
71:     window.addEventListener('keyup', e => send(false, e));
72:     function releaseAll() {
73:       for (const k of new Set(down.values())) Module._dg_key(0, k);
74:       down.clear();
75:     }
76:     window.addEventListener('blur', releaseAll);
77:     document.addEventListener('visibilitychange', () => { if (document.hidden) releaseAll(); });
78:     document.getElementById('canvas').addEventListener('pointerdown', unlockAudio);
79:     function buttonKey(k) {
80:       if (!Module._dg_key) return;
81:       unlockAudio(); Module._dg_key(1, k);
82:       setTimeout(() => Module._dg_key(0, k), 70);
83:       Module.canvas.focus();
84:     }
85:     document.getElementById('menu').addEventListener('click', () => buttonKey(27));
86:     document.getElementById('pause').addEventListener('click', () => buttonKey(255));
87:     document.getElementById('sound').addEventListener('click', () => {
88:       if (DoomAudio.context) DoomAudio.setMuted(!DoomAudio.muted);
89:       unlockAudio();
90:     });
91:     document.getElementById('volume').addEventListener('input', e => DoomAudio.setVolume(Number(e.target.value)/100));
92:     setInterval(() => {
93:       if (!Module._dg_paused) return;
94:       const paused = !!Module._dg_paused(), button = document.getElementById('pause');
95:       button.textContent = paused ? 'Resume' : 'Pause'; button.setAttribute('aria-pressed', String(paused));
96:     }, 100);
97: 
98:     var Module = {
99:       canvas: document.getElementById('canvas'),
100:       onAbort: w => { document.getElementById('status').textContent = `Game stopped: ${w}`; },
101:       print: t => console.log(t),
102:       printErr: t => console.warn(t),
103:       setStatus: t => { document.getElementById('status').textContent = t || 'Ready — click the game or press a key to enable sound'; },
104:       monitorRunDependencies: n => { if (n === 0) document.getElementById('status').textContent = 'Arrows move, Ctrl fire, Space use, Enter/Esc menu'; },
105:       onRuntimeInitialized: () => {
106:         document.getElementById('menu').disabled = false;
107:         document.getElementById('pause').disabled = false;
108:         document.getElementById('canvas').focus();
109:       },
110:     };
111:   </script>
112:   <script>
113:     // Surface a failed game-data (WAD) download instead of hanging on "Loading…".
114:     window.addEventListener('error', e => {
115:       if (e.target && e.target.src && /doom\.js$/.test(e.target.src))
116:         document.getElementById('status').textContent = 'Failed to load doom.js';
117:     }, true);
118:   </script>
119:   <script src="doom.js"></script>
120: </body>
121: </html>"}

